// =====================================================================
// PUNTO UNICO DE SALIDA. Todas las ramas convergen aca.
//
// Existe por una trampa concreta de n8n: despues de un nodo HTTP, $json
// pasa a ser la RESPUESTA del request, no tus datos. Si cada nodo de
// Chatwoot leyera $('Rama X'), reventaria en las ramas que no pasaron
// por X. Con un solo nodo comun, todos leen $('Armar salida') y siempre
// existe.
//
// Ademas es lo que permite tener UN nodo por accion (responder, notar,
// etiquetar, asignar, avisar) en vez de uno por rama.
// =====================================================================
const cfg = $('Config').first().json;

return $input.all().map((item) => {
  const j = item.json || {};

  // OJO: POST /labels de Chatwoot REEMPLAZA el set completo, no agrega.
  // Sin este merge, cualquier etiqueta que un agente puso a mano se pierde
  // en el proximo turno del bot.
  const base = j.modo === 'general' ? 'consulta-general' : 'reactivacion';
  const nuevas = Array.isArray(j.etiquetas) && j.etiquetas.length ? j.etiquetas : [base];
  const previas = Array.isArray(j.etiquetas_previas) ? j.etiquetas_previas : [];
  // Si este turno cancelo la reunion, 'agendado' queda desactualizada: la
  // sacamos del set aunque venga de una etiqueta previa. Es la UNICA
  // etiqueta que se descarta a proposito -- todas las demas se preservan.
  const etiquetas = [];
  for (const e of previas.concat(nuevas)) {
    const t = (e || '').toString().trim();
    if (!t || etiquetas.indexOf(t) !== -1) continue;
    if (j.cancelado === true && t === 'agendado') continue;
    // Si el cliente esta esperando en la videollamada AHORA, dejar la
    // conversacion como 'consulta-general' la esconde entre las consultas
    // frias. No lo es: hay una reunion en curso y alguien del otro lado.
    if (j.esperando_en_reunion === true && t === 'consulta-general') continue;
    etiquetas.push(t);
  }

  // =====================================================================
  // A QUIEN SE LE ASIGNA LA CONVERSACION CUANDO PASA A UNA PERSONA
  //
  // Regla del negocio: Damian atiende Argentina (+54) y Uruguay (+598),
  // Greta atiende todo el resto. Los ids viven en Config -- aca solo va la
  // regla, para que cambiar de persona sea tocar un solo lugar.
  //
  // Se comparan solo los digitos: el telefono puede venir con o sin '+',
  // con espacios o con guiones segun de donde salga.
  //
  // OJO CON EL ORDEN DE LOS PREFIJOS: no se pisan (54 vs 598 difieren en el
  // segundo digito), asi que da igual cual se evalue primero. Si algun dia
  // se suma un pais cuyo prefijo empiece igual que otro, hay que chequear
  // el mas largo PRIMERO.
  //
  // Si el telefono llegara vacio o sin codigo de pais, cae en Greta por ser
  // el cajon de "todo el resto". Es la opcion segura: la conversacion queda
  // asignada a alguien, no huerfana.
  const digitos = (j.telefono || '').toString().replace(/\D/g, '');
  const esArgUy = digitos.indexOf('54') === 0 || digitos.indexOf('598') === 0;
  // Tres datos de tres sistemas distintos: Chatwoot para asignar, Slack
  // para mencionar, y el nombre como respaldo si falta el id de Slack.
  const assignee_id = esArgUy ? cfg.CHATWOOT_AGENTE_AR_UY : cfg.CHATWOOT_AGENTE_RESTO;
  const asignado_slack = esArgUy ? cfg.CHATWOOT_AGENTE_AR_UY_SLACK : cfg.CHATWOOT_AGENTE_RESTO_SLACK;
  const asignado_a = esArgUy ? cfg.CHATWOOT_AGENTE_AR_UY_NOMBRE : cfg.CHATWOOT_AGENTE_RESTO_NOMBRE;

  // Se asigna y se avisa a Slack UNA SOLA VEZ: en el turno exacto en que la
  // conversacion se escala. 'ya_estaba_escalado' lo calcula 'Preparar Datos
  // Lead' y es true cuando la etiqueta 'necesita-humano' YA estaba antes de
  // este turno.
  //
  // Hoy el nodo 'Filtrar necesita-humano', que esta arriba de todo, ya corta
  // los mensajes de conversaciones escaladas antes de que lleguen aca. Esta
  // condicion queda igual como segunda baranda: cubre el caso de que la
  // etiqueta la ponga una persona a mano por otro camino.
  const asignar = etiquetas.indexOf('necesita-humano') !== -1 && j.ya_estaba_escalado !== true;

  return { json: {
    conversation_id: j.conversation_id,
    telefono: j.telefono || '',
    nombre: j.nombre || '',
    empresa: j.empresa || '',
    motivo_perdida: j.motivo_perdida || '',
    input: j.input || j.texto || '',
    modo: j.modo || 'normal',
    paso: j.paso || '',
    cierre: j.cierre || '',
    agendado: j.agendado === true,
    slot: (j.slot_final || j.slot_elegido || {}).etiqueta || '',
    email_final: j.email_final || '',
    mensaje_saliente: (j.mensaje_saliente || '').toString(),
    etiquetas: etiquetas,
    nota_agenda: (j.nota_agenda || '').toString(),
    asignar: asignar,
    assignee_id: assignee_id,
    asignado_slack: asignado_slack,
    asignado_a: asignado_a,
    // Se avisa al comercial cuando la conversacion pasa a una persona o
    // cuando hay reunion. Se deriva de la ETIQUETA, no de un campo suelto:
    // toda rama que promete "lo contacta un integrante del equipo" pone
    // 'necesita-humano', asi no hay forma de prometerlo y no avisar.
    avisar: etiquetas.indexOf('necesita-humano') !== -1 || j.agendado === true || j.cancelado === true,
    // Lo lee 'Armar mensaje Slack' para cambiar el aviso de tono: esto es
    // urgente y de minutos, no una consulta que alguien atiende cuando puede.
    esperando_en_reunion: j.esperando_en_reunion === true,
    // Resultado de la verificacion de agendamiento. Lo lee el aviso de
    // Slack para mostrarle al humano que horario quedo mal y cual era el
    // correcto, en vez de obligarlo a reconstruirlo.
    verificacion_agenda: j.verificacion_agenda || '',
    agendado_iso: j.agendado_iso || '',
    sugerido_iso: j.sugerido_iso || ''
  } };
});

// =====================================================================
// PROCESAR RESPUESTA — traduce lo que devolvio el modelo en algo que
// Chatwoot entienda: mensaje, etiquetas y motivo de cierre.
// =====================================================================
const pre = $('Preparar Datos Lead').first().json || {};
const isAudio = pre.tiene_audio === true;

const msgEscalar = function (nombre) {
  const n = (nombre || '').toString().trim();
  const apertura = n && n !== 'Contacto' ? 'Hola ' + n + ', e' : 'E';
  return apertura + 'sa consulta la puede responder mejor un especialista de nuestro equipo. Le derivo la conversacion y se comunican a la brevedad.';
};

const MSG_YA_ESCALADO = 'Ya le avisamos al equipo y se comunican a la brevedad.';

let r = '';
try {
  const item = $input.item.json || {};
  r = (item.output || item.text || item.response || '').toString();
} catch (e) { r = ''; }
r = r.trim();

// =====================================================================
// RESPUESTA FIJA -- LA RAMA QUE NO PASA POR EL MODELO.
//
// 'Preparar Datos Lead' resuelve solo cuatro casos sin consultar a la IA
// (opt-out, mensaje sin texto, tope de turnos y confirmacion sin
// contexto) y deja el texto listo en pre.respuestaFija.
//
// Esta guarda FALTABA: como esos items llegan sin salida de modelo, r
// quedaba vacio, mas abajo se interpretaba como "el modelo no contesto" y
// se ESCALABA. O sea que a quien pedia la baja se le respondia con el
// mensaje de derivacion a un especialista en vez del acuse de opt-out.
//
// Cada caso lleva su etiqueta: 'opt-out' es terminal (el bot no vuelve a
// hablar nunca), y los dos que PROMETEN una persona ponen
// 'necesita-humano' para que el aviso salga de verdad.
// =====================================================================
if (pre.accion === 'fija' && pre.respuestaFija) {
  const BASE_FIJA = pre.modo === 'general' ? 'consulta-general' : 'reactivacion';
  let etiquetasFijas = [BASE_FIJA];
  if (pre.bloqueado === 'optout') etiquetasFijas = [BASE_FIJA, 'opt-out'];
  else if (pre.bloqueado === 'tope' || pre.bloqueado === 'sin_texto') etiquetasFijas = [BASE_FIJA, 'necesita-humano'];
  return { json: Object.assign({}, pre, {
    mensaje_saliente: String(pre.respuestaFija).replace(/[¿¡]/g, '').trim(),
    etiquetas: etiquetasFijas,
    cierre: pre.bloqueado === 'optout' ? 'opt-out' : (pre.bloqueado === 'confirmacion_sin_contexto' ? 'despedida' : 'escalado'),
    fuera_de_tema: false,
    agendado: false,
    cancelado: false,
    esperando_en_reunion: false,
    email_final: pre.email_crm || '',
    nota_agenda: ''
  }) };
}

// Si el modelo devolvió [SILENCIO] o está vacío, no se envía ningún mensaje saliente
if (/^\[?\s*silencio\s*\]?$/i.test(r) || /^\[?\s*no_responder\s*\]?$/i.test(r)) {
  return { json: Object.assign({}, pre, {
    mensaje_saliente: '',
    etiquetas: pre.modo === 'general' ? ['consulta-general'] : ['reactivacion'],
    cierre: 'despedida',
    fuera_de_tema: false,
    agendado: false,
    cancelado: false,
    email_final: '',
    nota_agenda: ''
  }) };
}

const nombroLaTool = /(consultar|agendar)[a-z_ -]*calendly|calendly[ \t_-]*(consultar|agendar)/i.test(r);

let escalar = !r || r.indexOf('Error fetching') !== -1 || r.indexOf('429') !== -1 || nombroLaTool;

let agendado = false;

let motivoEscalar = '';
if (!r) motivoEscalar = 'sin_respuesta_del_modelo';
else if (r.indexOf('Error fetching') !== -1) motivoEscalar = 'error_fetching_en_output';
else if (r.indexOf('429') !== -1) motivoEscalar = 'rate_limit_429';
else if (nombroLaTool) motivoEscalar = 'nombro_la_tool_en_vez_de_llamarla';

let fueraDeTema = false;
if (/\bfuera[_ ]?de[_ ]?tema\b/i.test(r)) {
  fueraDeTema = true;
  escalar = false;
  r = 'Me voy a limitar a los temas de gestion de facturas y gastos, que es donde puedo serle util. Como viene hoy esa parte en ' + (pre.empresa || 'su empresa') + '?';
}

let emailFinal = pre.email_crm || '';

// ---------------------------------------------------------------------
// CORREO DE RESPALDO, SACADO DE LA CONVERSACION.
// 'Calendly - Verificar reunion' consulta por invitee_email. En una
// CONSULTA_GENERAL no hay correo en el CRM, asi que sin esto la
// verificacion queda ciega justo en los casos que mas importan.
// Caso real (02/09, Boris): escribio su correo en el chat y el CRM no lo
// tenia. Se toma el ULTIMO que haya escrito, ignorando los @xtract.app.
// ---------------------------------------------------------------------
if (!emailFinal) {
  const enConv = String(pre.transcripcion || '').match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi) || [];
  const ajenos = enConv.filter(function (e) { return e.toLowerCase().indexOf('@xtract.app') === -1; });
  if (ajenos.length) emailFinal = ajenos[ajenos.length - 1].toLowerCase();
}
const mEmail = r.match(/\[\s*email\s*:\s*([^\]]+)\]/i);
if (mEmail) {
  emailFinal = mEmail[1].trim();
  r = r.replace(/\[\s*email\s*:[^\]]*\]/ig, '').replace(/\s+/g, ' ').trim();
}

if (!fueraDeTema && /\[\s*agendado\s*\]/i.test(r)) {
  agendado = true;
  escalar = false;
  r = r.replace(/\[\s*agendado\s*\]/ig, '').replace(/\s+/g, ' ').trim();
  if (!r) r = 'Listo, quedo agendada la reunion. Le llega la invitacion por correo.';
}

// =====================================================================
// AVISO AL EQUIPO SIN PISAR EL MENSAJE.
//
// Caso real (28/08, conv 958): el cliente escribio "Nicolas estoy
// esperando en el meet". El modelo contesto "ya le aviso al equipo para
// que ingrese de inmediato" -- que es LA RESPUESTA APROBADA, palabra por
// palabra -- y el sistema no aviso a nadie: la deteccion de escalado
// buscaba 'escalar', 'derivo' o 'especialista', y ninguna aparecia.
// El cliente quedo esperando en la videollamada.
//
// No se resuelve con ESCALAR: esa palabra DESCARTA el texto del modelo y
// manda el aviso generico de derivacion, que aca no sirve.
// Este marcador avisa al equipo Y conserva el mensaje cortes.
// =====================================================================
let esperandoEnReunion = false;
if (/\[\s*avisar[_ ]?equipo\s*\]/i.test(r)) {
  esperandoEnReunion = true;
  r = r.replace(/\[\s*avisar[_ ]?equipo\s*\]/ig, '').replace(/\s+/g, ' ').trim();
}
// RED DE SEGURIDAD: si el modelo promete una accion humana con otras
// palabras (redacta distinto cada vez), igual se avisa. Sin esto, volver
// a fallar depende solo de como le salga la frase.
if (!esperandoEnReunion && /\b(le\s+)?(aviso|avisar|avisamos|comunico|notifico|informo|paso\s+el\s+(mensaje|dato))\b[^.]{0,45}\b(equipo|comercial|especialista|alguien|persona)\b/i.test(r)) {
  esperandoEnReunion = true;
}

let cancelado = false;
if (!fueraDeTema && /\[\s*cancelado\s*\]/i.test(r)) {
  r = r.replace(/\[\s*cancelado\s*\]/ig, '').replace(/\s+/g, ' ').trim();
  if (!agendado) {
    cancelado = true;
    escalar = false;
    if (!r) r = 'Listo, quedo cancelada la reunion.';
  }
}

if (!fueraDeTema && !agendado && !cancelado && !escalar) {
  if (/\bescalar\b|\bderiv(o|ar|amos)\b|\bespecialista\b/i.test(r)) { escalar = true; motivoEscalar = 'modelo_decidio_escalar'; }

  if (/no tengo (informaci|datos)|no cuento con|como (IA|modelo)|puedo inferir|probablemente sea/i.test(r)) {
    escalar = true;
    motivoEscalar = motivoEscalar || 'modelo_rompio_personaje';
  }
}

let rawMensaje = r;
if (escalar) {
  if (pre.ya_estaba_escalado) {
    rawMensaje = MSG_YA_ESCALADO;
  } else if (!r || r.indexOf('Error fetching') !== -1 || r.indexOf('429') !== -1 || nombroLaTool) {
    rawMensaje = msgEscalar(pre.nombre_corto);
  } else {
    rawMensaje = r.replace(/\[\s*DERIVAR[^\n\]]*\]/ig, '').trim() || msgEscalar(pre.nombre_corto);
  }
}

const mensaje = rawMensaje.replace(/[¿¡]/g, '').trim();

// =====================================================================
// SI EL MENSAJE YA LLEVA EL LINK, NO SE PIDE EL CORREO.
//
// Calendly le pide el correo al cliente en su propio formulario, asi que
// preguntarlo aca es redundante -- y reabre el ida y vuelta que el link
// vino justamente a cerrar.
//
// El prompt ya lo prohibe ("PROHIBIDO: pedirle el correo antes de pasar el
// link") y el modelo lo hizo igual en la prueba del 01/09:
//   "...Son 45 minutos y le llega la invitacion por correo. Tengo
//    registrado el correo soporte@..., me confirma que sigue vigente?"
//
// Se recorta SOLO la frase que PIDE el correo. La informativa ("le llega
// la invitacion por correo") se conserva, porque no genera ida y vuelta.
// Y solo aplica cuando hay link: en el reagendamiento pedir el correo SI
// hace falta para buscar la reunion.
// =====================================================================
const PIDE_CORREO = /\b(correo|mail|e-?mail)\b/i;
const ES_PEDIDO = /\?|me confirma|me pasa|me indica|cual es|necesito que|pasame|decime|indiqueme|confirmame|me lo pasa/i;
let mensajeFinal = mensaje;
if (/calendly\.com/i.test(mensajeFinal)) {
  const frases = mensajeFinal.split(/(?<=[.!?])\s+/);
  const filtradas = frases.filter(function (f) {
    return !(PIDE_CORREO.test(f) && ES_PEDIDO.test(f) && !/calendly\.com/i.test(f));
  });
  if (filtradas.length) mensajeFinal = filtradas.join(' ').trim();
}

let cierre = '';
if (agendado) cierre = 'agendado';
else if (cancelado) cierre = 'cancelado';
else if (escalar) cierre = 'escalado';
else if (/\badi[oó]s\b|hasta pronto|quedamos a disposicion|le agradezco la respuesta/i.test(mensaje)) {
  cierre = 'despedida';
}

const BASE = pre.modo === 'general' ? 'consulta-general' : 'reactivacion';
let etiquetas = [BASE];
// 'reunion-en-curso' es urgente y de minutos: se etiqueta aparte para
// poder filtrarla en Chatwoot y para que el aviso de Slack cambie de tono.
if (esperandoEnReunion) etiquetas = [BASE, 'necesita-humano', 'reunion-en-curso'];
if (agendado) etiquetas = [BASE, 'agendado'];
else if (cancelado) etiquetas = [BASE, 'cancelado'];
else if (escalar) etiquetas = [BASE, 'necesita-humano'];

const nota = agendado
  ? 'AGENDA_ESTADO ' + JSON.stringify({ etapa: 'agendado', registrado: new Date().toISOString() })
  : (cancelado
      ? 'AGENDA_ESTADO ' + JSON.stringify({ etapa: 'cancelado', registrado: new Date().toISOString() })
      : (escalar && motivoEscalar
          ? 'ESCALAR_DEBUG ' + JSON.stringify({ motivo: motivoEscalar, output_crudo: r.slice(0, 500), registrado: new Date().toISOString() })
          : ''));

return { json: Object.assign({}, pre, {
  mensaje_saliente: mensajeFinal,
  etiquetas: etiquetas,
  cierre: cierre,
  fuera_de_tema: fueraDeTema,
  esperando_en_reunion: esperandoEnReunion,
  agendado: agendado,
  cancelado: cancelado,
  email_final: emailFinal,
  nota_agenda: nota
}) };

const CFG = $('Config').first().json;
const MAX_TURNOS_HIST = parseInt(CFG.WA_MAX_TURNOS) || 12;
const MAX_TURNOS = parseInt(CFG.WA_MAX_TURNOS_BOT) || 0;   // 0 = sin tope

const KIND = (CFG.CALENDLY_LOCATION_KIND || '').toString().toLowerCase();
const MODALIDAD = KIND.indexOf('zoom') !== -1 ? 'Es una videollamada por Zoom'
  : KIND.indexOf('google') !== -1 ? 'Es una videollamada por Google Meet'
  : KIND.indexOf('teams') !== -1 ? 'Es una videollamada por Microsoft Teams'
  : KIND.indexOf('physical') !== -1 ? 'Es presencial'
  : 'Es una videollamada';
const INSTALAR = KIND.indexOf('physical') !== -1
  ? 'No aplica, la reunion es presencial.'
  : 'Con el link del correo alcanza. Si le ofrece descargar una aplicacion, puede entrar igual desde el navegador.';

const OPT_OUT = [
  /\bdar(me|nos)? de baja\b(?!\s+(a\s+)?(un|una|el|la|los|las|mi|su)?\s*(usuario|proveedor|factura|comprobante|cuenta|articulo|producto|empleado|centro|item|orden)\w*)/i,
  /\bsolicito la baja\b|\bbaja de la (lista|base)\b/i,
  /\b(stop|unsubscribe|desuscribir|desuscribime)\b/i,
  /no me (escrib|contact|manden|mande|llamen|molest)/i,
  /dejen de (escrib|molest|contact|mandar)/i,
  /\b(borr|elimin|sa[cq]|quit)\w*me\b/i,
  /(borren|elimin\w*|saquen|quiten)\s+(me|mi|mis)\b/i,
  /no quiero (que me|recibir|mas mensaje)/i,
  /reportar como spam|es spam|esto es spam/i
];
const MSG_OPT_OUT = 'Entendido. Damos de baja el contacto y no volveremos a escribirle. Disculpe la molestia.';
const MSG_TOPE = 'Prefiero que siga la conversacion un integrante del equipo comercial, que le va a poder dar mas detalle. Ya le paso el contacto.';
const MSG_SIN_TEXTO = 'Recibimos tu mensaje. En breve lo atiende una persona del equipo.';
// =====================================================================
// RESPUESTA A UN TEMPLATE, NO UN MENSAJE EN FRIO.
//
// Si la conversacion no tiene NINGUN mensaje nuestro y la persona solo
// dice "perfecto" / "dale" / "listo", no esta abriendo una conversacion:
// esta contestando algo que le mandamos por otro canal (el recordatorio
// de la reunion, la plantilla de reactivacion). En Chatwoot no queda
// rastro de eso, pero es la unica lectura posible -- nadie escribe
// "perfecto" a un numero desconocido de la nada.
//
// Por eso el texto ACUSA RECIBO en vez de saludar: "gracias por la
// respuesta" reconoce que hubo algo antes. La version anterior
// ("Perfecto, quedamos atentos.") era neutra y sonaba a que no sabiamos
// de que hablaba.
//
// Lo que NO se hace es inventar de que template se trata: no se nombra
// la reunion ni la propuesta, porque no tenemos como saber cual fue.
// =====================================================================
const msgConfirmacion = function (nombre) {
  const n = (nombre || '').toString().trim();
  const apertura = (n && n !== 'Contacto') ? 'Perfecto ' + n + ', g' : 'Perfecto, g';
  return apertura + 'racias por la respuesta. Quedamos atentos por cualquier consulta.';
};

// Saludo opcional + UNA palabra de confirmacion, y nada mas. Si el mensaje
// trae cualquier otra cosa NO matchea y sigue el camino normal al modelo.
const SOLO_CONFIRMACION = /^(?:(?:hola|que\s*tal|buen(?:os|as)?(?:\s*(?:dias?|tardes?|noches?))?)[\s,.!¡]*)*(?:perfecto|dale|listo|ok(?:ey|is)?|de\s*acuerdo|barbaro|genial|joya|excelente|buenisimo|de\s*diez|confirmado|correcto|si|sip|va)[\s,.!]*$/i;

// 'necesita-humano' NO esta aca a proposito: si estuviera, una vez escalada
// la conversacion el bot queda mudo para siempre, incluso si el cliente
// vuelve a escribir para confirmar algo simple ("ya estoy en la reunion").
// En cambio se deja pasar al modelo con la marca 'ya_estaba_escalado', asi
// puede responder algo natural (via la regla de CORTESIA) sin escalar de
// nuevo -- y si el modelo vuelve a fallar, 'Procesar Respuesta' usa esa
// misma marca para caer en un acuse de "ya avisamos" en vez de repetir el
// mensaje de escalacion completo como si fuera la primera vez.
const ETIQUETAS_TERMINALES = ['opt-out', 'no-contactar', 'escalado'];

const limpiar = s => (s || '').toString().replace(/\s+/g, ' ').trim();

const metas = $('Cruzar con contexto del CRM').all();
const salida = [];

$input.all().forEach((item, idx) => {
  const meta = (metas[idx] && metas[idx].json) || {};
  const b = item.json || {};

  let msgs = [];
  if (Array.isArray(b.payload)) msgs = b.payload;
  else if (Array.isArray(b)) msgs = b;
  else if (b.payload && Array.isArray(b.payload.payload)) msgs = b.payload.payload;

  if (!msgs.length) return;

  let agenda = {};
  for (const m of msgs) {
    const c = (m.content || '').toString();
    if (m.private !== true || c.indexOf('AGENDA_ESTADO ') !== 0) continue;
    try {
      const d = JSON.parse(c.slice('AGENDA_ESTADO '.length));
      if (d && d.etapa) agenda = d;
    } catch (e) { /* nota rota: se ignora */ }
  }

  let turnos = [];
  for (const m of msgs) {
    if (m.private === true) continue;
    const tipo = m.message_type;
    if (tipo === 2 || tipo === 'activity') continue;
    const t = limpiar(m.content);
    if (!t) continue;
    turnos.push({ rol: (tipo === 0 || tipo === 'incoming') ? 'CLIENTE' : 'NOSOTROS', texto: t });
  }

  const idsEntrantes = msgs
    .filter(m => m.private !== true && (m.message_type === 0 || m.message_type === 'incoming'))
    .map(m => parseInt(m.id) || 0);
  const idUltimo = idsEntrantes.length ? Math.max.apply(null, idsEntrantes) : 0;
  const idPropio = parseInt(meta.message_id) || 0;

  if (idPropio && idUltimo && idUltimo > idPropio) return;

  let turnoCliente = 0;
  let previo = '';
  for (const t of turnos) {
    if (t.rol === 'CLIENTE' && previo !== 'CLIENTE') turnoCliente++;
    previo = t.rol;
  }
  turnoCliente = turnoCliente || 1;

  const rafaga = [];
  for (let i = turnos.length - 1; i >= 0; i--) {
    if (turnos[i].rol !== 'CLIENTE') break;
    rafaga.unshift(turnos[i].texto);
  }
  const recorte = turnos.slice(-MAX_TURNOS_HIST);
  const transcripcion = recorte.map(t => t.rol + ': ' + t.texto).join('\n');

  const textoCliente = rafaga.length ? rafaga.join('. ') : limpiar(meta.texto);
  const etiquetas = (meta.etiquetas || []).map(e => e.toString().toLowerCase().trim());
  const emailCrm = /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/i.test((meta.email || '').trim())
    ? meta.email.trim().toLowerCase() : '';

  const turnosModelo = turnoCliente;
  const paso = turnoCliente <= 1 ? 1 : (turnoCliente === 2 ? 2 : 3);

  const telDigitos = (meta.telefono || '').toString().replace(/[^0-9]/g, '');
  const DATOS_QA = { empresa: meta.empresa || '', nombre: meta.nombre || '',
    telefono: meta.telefono || '', telefono_e164: telDigitos ? '+' + telDigitos : '',
    sistema: meta.sistema || '', pais: meta.pais || '' };
  const calendly_qa = (Array.isArray(CFG.CALENDLY_PREGUNTAS) ? CFG.CALENDLY_PREGUNTAS : [])
    .map(function (q) {
      const resp = (q.respuesta || '').toString().replace(/\{(\w+)(?:\|([^}]*))?\}/g, function (_, k, def) {
        const v = (DATOS_QA[k] || '').toString().trim();
        return v || (def || '').toString();
      }).trim();
      const o = { question: (q.pregunta || '').toString(), answer: resp };
      if (q.position !== undefined) o.position = q.position;
      return o;
    })
    .filter(function (q) { return q.question && q.answer; });

    // Cortar bucle infinito de despedidas / cortesías:
  // Si nuestro último mensaje ya fue una despedida/cierre y el cliente solo responde una cortesía breve,
  // se apaga el bot y NO se envía ningún mensaje saliente.
  const turnosNosotros = turnos.filter(t => t.rol === 'NOSOTROS');
  const ultimoNosotros = turnosNosotros.length ? turnosNosotros[turnosNosotros.length - 1].texto : '';
  const esDespedidaPrevia = /(que tenga (buen|un buen|excelente)|quedamos a (su )?disposici[oó]n|le agradezco|un saludo|hasta pronto|que disfrute|excelente d[ií]a)/i.test(ultimoNosotros);
  const esCortesiaCierre = /^(gracias|muchas gracias|mil gracias|perfecto|de diez|buen[ií]simo|genial|ok|listo|dale|igualmente|a usted(es)?|chau|saludos|de nada|abrazo|excelente).?$/i.test(textoCliente.trim());

  let accion = 'bot';
  let bloqueado = '';
  let respuestaFija = '';
  let modo = 'normal';

  const terminal = ETIQUETAS_TERMINALES.find(e => etiquetas.indexOf(e) !== -1);
  // La nota AGENDA_ESTADO es la fuente mas reciente. La etiqueta 'agendado'
  // de Chatwoot NUNCA se borra sola (el merge de 'Armar salida' es solo
  // aditivo, a proposito, para no pisar etiquetas puestas a mano) -- por eso
  // no alcanza con mirarla: si la ultima nota dice 'cancelado', gana la nota,
  // sin eso el TIPO queda pegado en POST_AGENDAMIENTO para siempre despues
  // de una cancelacion.
  const yaAgendado = agenda.etapa === 'cancelado'
    ? false
    : (etiquetas.indexOf('agendado') !== -1 || agenda.etapa === 'agendado');

  // Se pasa a 'Procesar Respuesta' para que, si el modelo vuelve a fallar en
  // esta misma conversacion, caiga en el acuse de "ya avisamos" en vez de
  // repetir el mensaje de escalacion completo como si fuera la primera vez.
  const yaEstabaEscalado = etiquetas.indexOf('necesita-humano') !== -1;

  if (terminal || (esDespedidaPrevia && esCortesiaCierre)) {
    // Si la conversación ya terminó y el cliente solo mandó "gracias/perfecto", salida silenciosa
    return;
  } else if (terminal) {
    return;
  } else if (!textoCliente) {
    accion = 'fija'; bloqueado = 'sin_texto'; respuestaFija = MSG_SIN_TEXTO;
  } else if (OPT_OUT.some(re => re.test(textoCliente))) {
    accion = 'fija'; bloqueado = 'optout'; respuestaFija = MSG_OPT_OUT;
  } else if (MAX_TURNOS > 0 && turnosModelo > MAX_TURNOS) {
    accion = 'fija'; bloqueado = 'tope'; respuestaFija = MSG_TOPE;
  } else if (turnosNosotros.length === 0 && SOLO_CONFIRMACION.test(textoCliente.trim())) {
    // =================================================================
    // "Hola perfecto" SIN NINGUN MENSAJE NUESTRO ANTES.
    //
    // Caso real (31/08, conv 1004): la conversacion entera era un unico
    // "Hola perfecto". El recordatorio de la reunion habia salido por
    // otro canal, asi que en Chatwoot no hay rastro. El modelo lo leyo
    // como un saludo suelto y contesto "En que puedo ayudarlo?" -- que
    // delante de alguien que acaba de confirmar suena a que no sabemos
    // quien es.
    //
    // El prompt ya prohibe esa pregunta generica ante una confirmacion,
    // pero tambien manda ofrecer ayuda ante un saludo, y "Hola perfecto"
    // es las dos cosas. Resolverlo aca lo saca del criterio del modelo.
    //
    // Se contesta corto y sin preguntar nada: si la persona queria algo,
    // lo va a decir en el mensaje siguiente.
    // =================================================================
    accion = 'fija'; bloqueado = 'confirmacion_sin_contexto';
    respuestaFija = msgConfirmacion(meta.primer_nombre);
  } else if (yaAgendado) {
    // yaAgendado va ANTES que el chequeo de 'conocido' a proposito: hay leads
    // que agendan reunion sin haber pasado por la lista de reactivacion (les
    // llega de otro canal, los agendo un comercial a mano, etc.) y escriben
    // despues para reagendar. Si 'conocido' ganara primero, entrarian como
    // CONSULTA_GENERAL, que tiene PROHIBIDO usar las herramientas de Calendly,
    // y no podrian reagendar ni cancelar una reunion que si existe de verdad.
    modo = 'postventa';
  } else if (meta.conocido === false) {
    modo = 'general';
  }

  const TIPOS = { normal: 'REACTIVACION', postventa: 'POST_AGENDAMIENTO', general: 'CONSULTA_GENERAL' };
  const tipoConversacion = TIPOS[modo] || 'REACTIVACION';

  let ficha;
  if (modo === 'general') {
    ficha = '- No esta en el piloto. No tenemos ningun dato de esta persona.';
  } else {
    const L = [];
    const push = (k, v) => { const x = limpiar(v); if (x) L.push('- ' + k + ': ' + x); };
    push('Nombre', meta.nombre);
    push('Empresa', meta.empresa);
    push('Pais', meta.pais);
    push('Sistema ERP', meta.sistema);
    push('Facturas mensuales', meta.cantidad_facturas);
    // EL QUE ESCRIBE ES SIEMPRE NICOLAS.
    // La plantilla de apertura dice textual "Te escribe Nico" a TODOS los
    // leads, sin importar quien figure como owner en el CRM. Asi que el
    // interlocutor es siempre el mismo.
    //
    // Antes la ficha decia "Comercial que lo atendio: <owner>", y el modelo lo
    // leia como un tercero: escribio "Nicolas me comentaba que habiamos
    // quedado..." hablando de si mismo en tercera persona, justo despues de
    // haberse presentado como Nico. Para el cliente eso es un cambio de
    // interlocutor sin aviso.
    //
    // El owner NO se pone en la ficha: no aporta nada que el modelo pueda
    // decir sin romper el personaje. Lo que se hizo con ese lead se cuenta en
    // primera persona del plural ("habiamos quedado", "quedamos en").
    L.push('- Lo atendiste VOS. Hablá en primera persona: "habíamos quedado", "quedamos en". NUNCA nombres a un comercial en tercera persona.');

    const hitos = [];
    if (limpiar(meta.fecha_discovery)) hitos.push('discovery el ' + limpiar(meta.fecha_discovery));
    if (limpiar(meta.hubo_reunion) === 'si') hitos.push('tuvo reunion con el equipo');
    if (limpiar(meta.fecha_propuesta)) hitos.push('se le envio propuesta el ' + limpiar(meta.fecha_propuesta));
    if (hitos.length) L.push('- Historia con nosotros: ' + hitos.join('; '));

    const dias = parseInt(meta.dias_desde_perdida);
    if (!isNaN(dias)) L.push('- Se marco como perdida hace ' + dias + ' dias');

    if (limpiar(meta.motivo_perdida)) {
      L.push('- Lo ultimo que nos dijeron (textual, respetalo): "' + limpiar(meta.motivo_perdida) + '"');
    } else {
      L.push('- No quedo registrado el motivo de la perdida. NO inventes uno.');
    }
    ficha = L.join('\n') || '- Sin datos adicionales en el CRM.';
  }

  salida.push({ json: Object.assign({}, meta, {
    accion: accion,
    bloqueado: bloqueado,
    respuestaFija: respuestaFija,
    input: textoCliente,
    paso: paso,
    turnoCliente: turnoCliente,
    turnos_modelo: turnosModelo,
    tipo_conversacion: tipoConversacion,
    nombre_corto: meta.primer_nombre || 'Contacto',
    ficha: ficha,
    modalidad: MODALIDAD,
    instalar: INSTALAR,
    email_crm: emailCrm,
    transcripcion: transcripcion,
    modo: modo,
    calendly_qa: calendly_qa,
    agenda_etapa: agenda.etapa || '',
    ya_estaba_escalado: yaEstabaEscalado
  }) });
});

return salida;

// =====================================================================
// CRUCE CON EL CRM. Antes esto era un candado: el que no estaba en la
// lista del piloto se descartaba. Ya no, porque el bot tambien contesta
// consultas generales de gente que nunca estuvo en el piloto.
//
// Lo que hace ahora es CLASIFICAR, no filtrar:
//   conocido: true  -> lead del piloto, con toda su historia comercial
//   conocido: false -> consulta general, sin ficha y sin pitch
//
// Quien protege de pisarle la conversacion a una persona es el candado
// del asignado, en 'Filtrar solo entrantes'.
// =====================================================================
const soloDigitos = s => (s || '').toString().replace(/[^0-9]/g, '');

// Compara los ultimos 8 digitos: sortea diferencias de prefijo pais / 9 / 15
const cola = s => { const d = soloDigitos(s); return d.length >= 8 ? d.slice(-8) : ''; };

const porTel = {};
const porConv = {};
try {
  for (const it of $('Leer Enviados WA').all()) {
    const r = it.json;
    const c = cola(r.telefono);
    if (c) porTel[c] = r;
    const conv = (r.chatwoot_conversation_id || '').toString().trim();
    if (conv) porConv[conv] = r;
  }
} catch (e) {}

// PUERTA DE PRUEBA: estos telefonos entran como leads del piloto aunque
// no tengan una fila en la hoja ni atributos en Chatwoot. Sin esto caen en
// modo 'general', y en ese modo el prompt le PROHIBE al modelo usar las
// herramientas de Calendly -- o sea que no se podria probar el agendamiento.
// Se comparan los ultimos 8 digitos, igual que el resto del cruce.
const PRUEBA = new Set(
  ((($('Config').first().json || {}).WA_TELEFONOS_PRUEBA) || [])
    .map(t => cola(t)).filter(Boolean)
);

const txt = v => (v === null || v === undefined) ? '' : String(v);
const salida = [];

for (const it of $('Filtrar solo entrantes').all()) {
  const m = it.json;
  // Orden de preferencia:
  //  1) los custom_attributes que ya vinieron en el webhook (sin red)
  //  2) la fila de la hoja, si el IF de arriba la hizo leer
  const c = (m.tiene_contexto ? m.crm : null)
    || porConv[String(m.conversation_id)]
    || porTel[cola(m.telefono)]
    || null;

  // NO conocido -> consulta general. No hay ficha ni historia comercial:
  // los campos van vacios a proposito y el prompt cambia de modo.
  // La lista blanca solo AGREGA: si el numero ya estaba en el CRM, se usa
  // su ficha real. Nunca pisa datos buenos con una ficha vacia.
  const esPrueba = PRUEBA.has(cola(m.telefono));
  const conocido = !!c || esPrueba;
  const d = c || {};

  salida.push({ json: {
    conversation_id: m.conversation_id,
    telefono: m.telefono,
    texto: m.texto,
    soportado: m.soportado,
    message_id: m.message_id,
    etiquetas: m.etiquetas || [],
    etiquetas_previas: m.etiquetas || [],
    nombre: txt(d.nombre || m.nombre_wa),
    // Vacio si no hay nombre, NO 'Hola': este campo lo lee el prompt del
    // agente como el nombre del interlocutor. Con el default viejo, a un
    // contacto sin nombre en WhatsApp el modelo lo trataba de "Hola".
    primer_nombre: (txt(d.nombre || m.nombre_wa).split(' ')[0]) || '',
    empresa: txt(d.empresa),
    motivo_perdida: txt(d.motivo_perdida),
    sistema: txt(d.sistema),
    pais: txt(d.pais),
    // El atributo del correo cambio de nombre en Chatwoot y se manejaron
    // dos variantes ('emailsdk' / 'emailkdm'). Se aceptan las dos mas el
    // nombre viejo: si se lee el equivocado, el bot le pide el correo a
    // gente que ya lo tiene cargado, y eso no da ningun error visible.
    // La hoja de Sheets sigue usando la columna 'email'.
    email: txt(d.emailsdk || d.emailkdm || d.email_kdm || d.email),
    owner: txt(d.owner),
    cantidad_facturas: txt(d.cantidad_facturas),
    fecha_discovery: txt(d.fecha_discovery),
    fecha_reunion: txt(d.fecha_reunion),
    fecha_propuesta: txt(d.fecha_propuesta),
    dias_desde_perdida: txt(d.dias_desde_perdida),
    hubo_reunion: txt(d.hubo_reunion),
    calificacion: txt(d.calificacion),
    fecha_envio: txt(d.fecha_envio),
    // Se agrega para poder actualizar la card real en Notion cuando se
    // confirma un agendamiento -- antes se leia de la hoja pero se perdia
    // aca, nunca salia de este nodo.
    notion_page_id: txt(d.notion_page_id),
    conocido: conocido
  } });
}

return salida;

// =====================================================================
// CANDADO 1: Chatwoot NO es exclusivo de este piloto.
// El webhook message_created llega por TODA la cuenta, asi que hay que
// descartar activamente lo que no sea de este flujo.
// =====================================================================
const INBOX_PERMITIDO = ($('Config').first().json.CHATWOOT_INBOX_ID || '').toString().trim();
const salida = [];

// ⚠️ $input NO es el webhook: es el nodo 'Config', que esta en el medio y
// REEMPLAZA los items (hace return [{ json: {...} }]). Con $input.all() se
// recorria la config, message_type venia undefined y SE DESCARTABA TODO
// mensaje, siempre, sin ningun error visible.
// El payload real se lee del webhook por nombre.
for (const item of $('Chatwoot - message_created').all()) {
  const raw = item.json || {};
  const p = raw.body || raw;

  // Solo el evento que nos interesa
  if (p.event && p.event !== 'message_created') continue;

  // ANTI-LOOP: el bot no puede responderse a si mismo
  const rawType = p.message_type != null ? p.message_type.toString().toLowerCase() : '';
  if (rawType !== 'incoming' && rawType !== '0') continue;

  // Las notas internas de los agentes no son del cliente
  if (p.private === true) continue;

  // CANDADO por inbox: si esta configurado, solo ese inbox
  const inbox = ((p.inbox && p.inbox.id) || p.inbox_id || '').toString().trim();
  if (INBOX_PERMITIDO && inbox && inbox !== INBOX_PERMITIDO) continue;

  const attachments = Array.isArray(p.attachments) ? p.attachments : [];
  const audioAttachment = attachments.find(a => a.file_type === 'audio' || (a.content_type && a.content_type.startsWith('audio/')));
  const esAudio = !!audioAttachment;
  const audioUrl = audioAttachment ? (audioAttachment.data_url || audioAttachment.url || '') : '';
  const texto = (p.content || '').toString().trim();
  const conv = (p.conversation && p.conversation.id) || p.conversation_id || null;
  if (!conv) continue;

  // ETIQUETAS de la conversacion: son el estado persistente del bot.
  // No hay base propia -- Chatwoot ya es el dueno del hilo y de su estado.
  // OJO: la forma exacta del payload de message_created hay que verificarla
  // contra la instancia real; por eso se leen las tres variantes conocidas.
  const cv = p.conversation || {};
  const etiquetas = []
    .concat(Array.isArray(cv.labels) ? cv.labels : [])
    .concat(Array.isArray(cv.label_list) ? cv.label_list : [])
    .concat(Array.isArray(p.labels) ? p.labels : [])
    .map(e => (e && e.title ? e.title : e).toString());

  // =================================================================
  // CLASIFICACION TEMPRANA: piloto o consulta general.
  //
  // El workflow 1 le pone 'reactivacion' a cada conversacion del piloto.
  // Si la tiene, hace falta el contexto del CRM. Si NO la tiene, es una
  // consulta general y no hay CRM que buscar: se saltea Google Sheets
  // entero. Eso es lo que evita que cada mensaje ajeno se traiga la hoja
  // completa y queme la cuota de lectura (60/min).
  const esPiloto = etiquetas.some(e => e.toLowerCase().trim() === 'reactivacion');

  // Si el payload NO trae etiquetas no podemos saber si es del piloto.
  // En ese caso NO se decide aca: se hace la busqueda en la hoja y decide
  // 'Cruzar con contexto'. Filtrar por un campo ausente dejaria al bot mudo
  // con todo el mundo y sin ningun error visible.
  const esGeneral = etiquetas.length > 0 && !esPiloto;

  // =================================================================
  // CANDADO NUEVO: NO LE PISES LA CONVERSACION A UN HUMANO.
  //
  // Este reemplaza al descarte por etiqueta. Antes, todo lo que no fuera
  // del piloto se tiraba, y eso alcanzaba como proteccion. Ahora el bot
  // TAMBIEN contesta consultas generales, asi que el unico limite que
  // queda es este: si la conversacion ya tiene un agente asignado, es de
  // el. El bot se calla.
  //
  // Solo corta cuando HAY asignado. Si el campo no viene en el payload,
  // no se descarta nada: mismo criterio defensivo que con las etiquetas.
  // =================================================================
  const cvMeta = cv.meta || {};
  const asignado = (cvMeta.assignee && cvMeta.assignee.id)
    || (cv.assignee && cv.assignee.id) || cv.assignee_id || null;
  if (asignado) continue;

  const sender = p.sender || {};

  // =================================================================
  // CONTEXTO DEL CRM, DIRECTO DEL WEBHOOK.
  // El WF1 lo deja en los custom_attributes del contacto de Chatwoot.
  // Si viene aca, el WF2 NO necesita leer la hoja de Sheets: se ahorra
  // una lectura de la API de Google por cada mensaje entrante.
  //
  // 'empresa' y 'motivo_perdida' se usan de testigo: un contacto puede
  // existir en Chatwoot sin haber pasado nunca por el WF1, y en ese caso
  // los atributos vienen vacios y hay que caer a la hoja igual.
  // =================================================================
  const attrs = (sender.custom_attributes && typeof sender.custom_attributes === 'object')
    ? sender.custom_attributes : {};
  const tieneContexto = !!(attrs.empresa || attrs.motivo_perdida);
  const tel = (sender.phone_number || sender.identifier || '').toString().replace(/[^0-9]/g, '');

  salida.push({ json: {
    conversation_id: conv,
    contact_id: sender.id || null,
    inbox_id: inbox,
    telefono: tel,
    nombre_wa: (sender.name || '').toString(),
    texto: texto,
    etiquetas: etiquetas,
    estado_conversacion: (cv.status || '').toString(),
    es_piloto: esPiloto,
    es_general: esGeneral,
    soportado: texto.length > 0 || esAudio,
    es_audio: esAudio,
    audio_url: audioUrl,
    message_id: p.id || null,
    crm: attrs,
    tiene_contexto: tieneContexto
  } });
}

return salida;

// Unico lugar de configuracion del workflow.
// Esta instancia de n8n corre con N8N_BLOCK_ENV_ACCESS_IN_NODE: $env tira
// "access to env vars denied" y el `|| default` NO salva, porque la excepcion
// se tira al tocar $env. Por eso la config vive aca.
// Todo nodo aguas abajo lee con: $('Config').first().json.LO_QUE_SEA
return [{ json: {
  // --- Chatwoot ---
  CHATWOOT_URL: 'https://chatwoot.xtract.app',               // sin barra final
  CHATWOOT_ACCOUNT_ID: '1',
  CHATWOOT_INBOX_ID: '1',     // inbox de WhatsApp

  // =====================================================================
  // QUIEN ATIENDE UNA CONVERSACION ESCALADA
  //
  // Cada persona tiene TRES datos, y los tres son de sistemas distintos:
  //   _ID    -> id numerico de agente de CHATWOOT. Es el que pide
  //             assignee_id al asignar la conversacion. Sale de
  //             GET https://chatwoot.xtract.app/api/v1/accounts/1/agents
  //             (ese endpoint pide token de administrador).
  //   _SLACK -> member id de SLACK. Es el que arma la mencion <@ID> del
  //            aviso. NO tiene nada que ver con el de Chatwoot. Sale de
  //            GET https://slack.com/api/users.list (scope users:read).
  //   _NOMBRE-> solo para poder escribir el nombre si algun dia falta el
  //            id de Slack y no se puede mencionar.
  //
  // Si cambia la persona, se cambian LOS TRES juntos.
  // =====================================================================
  CHATWOOT_AGENTE_AR_UY: 35,                          // Chatwoot
  CHATWOOT_AGENTE_AR_UY_SLACK: 'U09PYEWUHGF',         // Slack
  CHATWOOT_AGENTE_AR_UY_NOMBRE: 'Damian Deggeller',   // atiende +54 (Argentina) y +598 (Uruguay)

  CHATWOOT_AGENTE_RESTO: 34,                          // Chatwoot
  CHATWOOT_AGENTE_RESTO_SLACK: 'U096BLX5864',         // Slack
  CHATWOOT_AGENTE_RESTO_NOMBRE: 'Greta Bruno',        // todos los demas paises

  // --- Hoja de control del piloto ---
  WA_SHEET_URL: 'https://docs.google.com/spreadsheets/d/1w6wVAuYmHjI8Fk4b3S1VLxAcgSSQkUjHOTrE1enmaP8/edit',

  // --- Avisos ---
  // El canal de Slack NO vive aca: se elige con el selector del nodo
  // "Postear en Slack" (#consultas-whatsapp). Habia un WA_SLACK_CHANNEL
  // con placeholder que no leia ningun nodo -- se saco para no dejar dos
  // fuentes de verdad, una de ellas muerta.

  // --- Calendly (Scheduling API: REQUIERE plan pago de Calendly) ---
  // Los tools del agente leen estos valores. EVENT_TYPE, la zona horaria y
  // LOCATION_KIND van fijos en el nodo tool: el modelo no los puede tocar.
  CALENDLY_EVENT_TYPE: 'https://api.calendly.com/event_types/a382fbef-fc03-4a33-ae47-90024c6b6714', // https://api.calendly.com/event_types/XXXX
  // Credencial de Calendly en uso: Micaela Marcos (micaela.marcos@xtract.app).
  // Los dos URIs salen de GET https://api.calendly.com/users/me con esa
  // credencial: ORG = resource.current_organization, USER = resource.uri
  //
  // OJO -- buscar_reunion_calendly y "Calendly - Verificar reunion" filtran
  // por ORG_URI, NO por USER_URI. Con user= solo se ven las reuniones de
  // Micaela, y los clientes tambien agendan con otros comerciales (Nico,
  // Jesus, etc.): esas quedaban invisibles y el bot respondia "no me figura
  // ninguna reunion". Con organization= se busca en toda la cuenta.
  CALENDLY_ORG_URI: 'https://api.calendly.com/organizations/4992c36c-b972-443c-b6b5-e4c260e9903e',
  // Queda por si alguna vez hace falta acotar a un solo organizador. Hoy no se usa.
  CALENDLY_USER_URI: 'https://api.calendly.com/users/f5345d9d-5241-445f-bf6d-5d9b349155a9',
  // Desde cuando se busca. 0 = desde ahora. La tool de disponibilidad la
  // usa, asi que si falta queda en 0 sin que nadie se entere.
 CALENDLY_DESDE_DIAS: 0,
  CALENDLY_DIAS: 21,              // ventana de disponibilidad (endpoint admite hasta 31)
  CALENDLY_OPCIONES: 3,           // horarios que se le piden al modelo que ofrezca
  CALENDLY_HORA_DESDE: 9,         // horario laboral ARGENTINO
  CALENDLY_HORA_HASTA: 18,
  CALENDLY_LOCATION_KIND: 'google_conference',
  // Duracion real del evento en Calendly. El bot la dice cuando le preguntan
  // "cuanto dura", asi que si cambias el event type, cambiala aca tambien.
  // 45, no 30. El event type real dura 45 y el bot venia diciendo 30:
  // verificado contra la API el 01/09 (GET /event_types -> duration: 45).
  CALENDLY_DURACION_MIN: 45,
  // Link publico de Calendly. El bot YA NO agenda: manda este link y el
  // cliente elige. Se saco el agendamiento por herramienta porque el modelo
  // alucinaba fechas -- caso real del 01/09: consulto disponibilidad del
  // jueves 3, Calendly le devolvio el 3, y agendo el 10. El cliente cancelo
  // esa reunion el mismo dia.
  //
  // Event type DEDICADO al piloto: "Reactivacion Xtract" (45 min). Se eligio
  // este y no 'xtractapp/30min' ("Xtract Web") justamente para no mezclar las
  // reuniones del piloto con las que entran por el formulario del sitio: si se
  // mezclan, no hay forma de medir cuantas genero la reactivacion.
  //
  // Es un link de tipo /d/ (event type oculto del listado publico). Es
  // reutilizable y compartible: no se agota con un uso.
  CALENDLY_LINK: 'https://calendly.com/d/d3mj-qn8-mkp/reactivacion-xtract',
  CALENDLY_PREGUNTAS: [
    // La UNICA obligatoria. Es el numero de WhatsApp desde el que escribio
    // el cliente: SIEMPRE existe, porque es como llego el mensaje.
    //
    // SIN VALOR POR DEFECTO A PROPOSITO. Un numero inventado terminaria
    // escrito en la reserva real y el comercial lo leeria como si fuera el
    // del cliente. Si algun dia llegara vacio, la pregunta se omite y
    // Calendly rechaza el alta con un error visible -- que es lo correcto.
    { position: 1, pregunta: 'Número de teléfono', respuesta: '{telefono_e164}' },
    // Opcional. Se usa para dejar constancia de que la reunion la coordino
    // el bot: sin esto, el comercial la lee como una reserva normal.
    { position: 0, pregunta: 'Cuéntenos algo que nos ayude a prepararnos para la reunión.',
      respuesta: 'Reunion coordinada por el asistente de reactivacion de Closed Lost ({empresa|empresa sin identificar}, ERP: {sistema|no informado}). El cliente acepto por WhatsApp.' }
  ],
  // --- PUERTA DE PRUEBA ---
  // Numeros que entran al flujo COMPLETO aunque no esten en la hoja ni
  // tengan atributos en Chatwoot. Se los trata como leads del piloto: con
  // ficha vacia, pero con modo normal y con las herramientas de Calendly
  // habilitadas, que es lo que hace falta para probar el agendamiento.
  //
  // ⚠️ VACIAR ESTA LISTA ANTES DEL PILOTO REAL. Mientras tenga numeros,
  // esos telefonos van a ser tratados como leads aunque no lo sean.
  // [] la desactiva por completo.
  WA_TELEFONOS_PRUEBA: ['+5493624900418', '+5493624009270'],

  // --- Buffer de rafagas ---
  // En WhatsApp nadie escribe un parrafo: manda "hola" / "che" / "una
  // consulta" en 5 segundos. Cada uno dispara una ejecucion. Se espera el
  // silencio y contesta UNA sola, con todo junto.
  WA_ESPERA_RAFAGA_SEG: 8,

  // --- Barandas de la conversacion ---
  WA_MAX_TURNOS: 12,     // turnos de historial que se le pasan al modelo
  // Mensajes conversados con el modelo antes de pasarlo a un humano.
  // OJO: desde que el agendamiento lo maneja el modelo con tools, los turnos
  // de coordinar horario y confirmar el mail SI cuentan aca. Por eso 12 y no
  // 8: con 8, un cliente que esta confirmando el correo se escala solo
  // -- justo el que estaba por cerrar. 0 lo desactiva por completo.
  WA_MAX_TURNOS_BOT: 12
} }];

// =====================================================================
// VERIFICACION CONTRA CALENDLY -- LA FUENTE, NO EL MODELO.
//
// Entra en DOS situaciones (ver el IF de arriba):
//   a) el modelo dijo que agendo   -> ¿existe la reunion de verdad?
//   b) el modelo decidio escalar   -> ¿no sera que SI se agendo?
//
// El caso (b) es real: 02/09, conv 1058 (Boris). El modelo agendo bien,
// cancelo la vieja, y volvio a llamar a agendar con el MISMO horario. La
// segunda llamada choco contra su propia reserva:
//   {"message":"Esa hora esta completa","code":"already_filled"}
// Lo leyo como fallo y respondio ESCALAR. La reunion estaba perfecta y al
// cliente le llego el mensaje de derivacion a un especialista.
//
// POR QUE ACA Y NO LEYENDO LA HERRAMIENTA: los nodos-herramienta del
// agente guardan su salida bajo 'ai_tool', nunca bajo 'main', y
// $('nodo').all() lee 'main'. Desde un Code node son ilegibles. El unico
// dato confiable es esta consulta HTTP a Calendly.
// =====================================================================
const pre = $('Procesar Respuesta').first().json || {};

let reuniones = [];
let lectura = 'sin_datos';
try {
  const j = $input.first().json || {};
  if (Array.isArray(j.collection)) {
    lectura = 'ok';
    reuniones = j.collection.filter(function (e) { return e && e.status === 'active'; });
  }
} catch (e) { lectura = 'error'; }

// Sin respuesta legible de Calendly no se juzga: se deja lo que decidio el
// modelo. Un falso positivo aca le arruina la reunion a un cliente.
if (lectura !== 'ok') {
  return { json: Object.assign({}, pre, { verificacion_agenda: 'sin_datos' }) };
}

const aART = function (iso) {
  try {
    return new Date(iso).toLocaleString('es-AR', {
      timeZone: 'America/Argentina/Buenos_Aires',
      weekday: 'long', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit'
    });
  } catch (e) { return String(iso); }
};

// (b) IBA A ESCALAR PERO LA REUNION EXISTE -> se confirma.
if (pre.cierre === 'escalado' && reuniones.length) {
  const ev = reuniones[0];
  return { json: Object.assign({}, pre, {
    verificacion_agenda: 'escalada_cancelada_reunion_existe',
    agendado: true,
    cancelado: false,
    cierre: 'agendado',
    etiquetas: [(pre.modo === 'general' ? 'consulta-general' : 'reactivacion'), 'agendado'],
    mensaje_saliente: ('Listo, quedo confirmada la reunion para el ' + aART(ev.start_time) +
                       ' (hora de Argentina). Le llega la invitacion por correo.').replace(/[¿¡]/g, ''),
    agendado_iso: ev.start_time,
    nota_agenda: 'AGENDA_ESTADO ' + JSON.stringify({ etapa: 'agendado', via: 'verificacion_calendly', registrado: new Date().toISOString() })
  }) };
}

// (a) DIJO QUE AGENDO PERO CALENDLY NO MUESTRA NADA -> no se le confirma.
if (pre.agendado === true && !reuniones.length) {
  return { json: Object.assign({}, pre, {
    verificacion_agenda: 'dijo_agendado_pero_no_existe',
    agendado: false,
    cierre: 'escalado',
    etiquetas: [(pre.modo === 'general' ? 'consulta-general' : 'reactivacion'), 'necesita-humano', 'agenda-a-revisar'],
    mensaje_saliente: 'Disculpe, quiero confirmar bien el horario antes de dejarlo agendado. Le escribe un integrante del equipo en un momento para cerrarlo.',
    nota_agenda: 'AGENDA_REVISAR ' + JSON.stringify({ motivo: 'el modelo confirmo una reunion que Calendly no muestra', registrado: new Date().toISOString() })
  }) };
}

// Coinciden: se deja pasar tal cual.
return { json: Object.assign({}, pre, {
  verificacion_agenda: 'ok',
  agendado_iso: reuniones.length ? reuniones[0].start_time : ''
}) };

// =====================================================================
// Aviso a Slack cuando una conversacion se escala a una persona.
//
// Cuelga detras de "Hay que asignar?", asi que dispara UNA SOLA VEZ por
// conversacion: en el turno exacto en que se pone la etiqueta
// 'necesita-humano'. Los mensajes siguientes del cliente NO vuelven a
// avisar -- ademas 'Filtrar necesita-humano', arriba de todo, ya los corta
// antes de que entren al flujo.
// =====================================================================
const cfg = $('Config').first().json;
const s = $('Armar salida').first().json;

// =====================================================================
// POR QUE EL CRUCE SE HACE ACA Y NO EN EL FILTRO DE NOTION
//
// En Notion los telefonos NO estan normalizados: la misma persona puede
// cargar +5492345890912, +54 9 2345 890912 o +549234589-0912. El filtro
// 'contains' de Notion busca sobre el TEXTO CRUDO, asi que:
//
//   guardado : +549234589-0912
//   digitos  : 5492345890912  -> ultimos 8: 45890912
//   crudo    : ...4589-0912   -> NO contiene '45890912' (el guion lo parte)
//
// Resultado: 0 filas, y el aviso saldria diciendo "sin card" para un
// cliente que SI esta cargado. Ningun substring salva esto -- seria
// adivinar como tipeo el numero quien lo cargo.
//
// Por eso Notion devuelve todas las cards con telefono y el cruce se hace
// aca, sobre SOLO DIGITOS, que es lo unico que aguanta cualquier formato.
// El precio es paginar la base en cada escalada; son pocas por dia.
//
// Si algun dia la base se hace grande, la solucion de fondo es una
// propiedad ya normalizada en Notion, no un filtro mas ingenioso.
// =====================================================================
const soloDigitos = (v) => String(v == null ? '' : v).replace(/\D/g, '');

// Se comparan los ultimos 8 digitos: alcanza para identificar sin depender
// del codigo de pais ni del 9 que Argentina mete despues del 54. Menos de
// 8 daria falsos positivos, asi que si el numero es mas corto no se cruza
// con nada y el aviso sale igual, avisando que no encontro card.
const target8 = soloDigitos(s.telefono).slice(-8);

// El nodo de Notion tiene alwaysOutputData prendido. Sin eso, cuando no
// encuentra ninguna card devuelve 0 items y n8n saltea todo lo de abajo:
// Slack no avisaria nunca. Y ese es justo el caso MAS importante -- un
// numero que no esta en el CRM pidiendo hablar con alguien.
// El precio es que puede llegar un item vacio {}, que se descarta aca.
const pages = target8.length < 8 ? [] : $input.all()
  .map((i) => i.json)
  .filter((p) => {
    if (!p || !p.id || !p.url) return false;
    return soloDigitos(p.property_whatsapp_kdm).slice(-8) === target8;
  });

let bloqueCard;
if (pages.length === 0) {
  bloqueCard = ':warning: Sin card en Notion para este numero';
} else {
  bloqueCard = pages.slice(0, 3).map((p) => {
    const nombreCard = p.property_nombre_oportunidad || p.name || 'Card sin nombre';
    const status = p.property_status ? ' | ' + p.property_status : '';
    // Owner viene como array de mails. Se muestra solo el nombre de pila:
    // 'damian.deggeller@xtract.app' -> 'Damian'.
    const ownerEmail = Array.isArray(p.property_owner) ? p.property_owner[0] : p.property_owner;
    let owner = '';
    if (ownerEmail) {
      const pila = String(ownerEmail).split('@')[0].split('.')[0];
      owner = ' | Owner: ' + pila.charAt(0).toUpperCase() + pila.slice(1);
    }
    return ':link: <' + p.url + '|' + nombreCard + '>' + status + owner;
  }).join('\n');
  if (pages.length > 3) {
    bloqueCard += '\n_(+' + (pages.length - 3) + ' cards mas con este numero)_';
  }
}

// =====================================================================
// LA MENCION TIENE QUE SER <@ID>, NO EL NOMBRE
//
// Escribir "Damian Deggeller" en el texto queda lindo y NO LE NOTIFICA A
// NADIE: es texto plano. Slack solo notifica con la sintaxis <@U09PYEWUHGF>,
// donde ese id es el member id de SLACK -- no el de Chatwoot, que es de
// otro sistema y no sirve para esto.
//
// El fallback al nombre existe para que, si algun dia falta el id en
// Config, el canal reciba "Damian Deggeller" en vez de un "<@>" roto.
// =====================================================================
// Con el cliente esperando en la sala no alcanza con nombrar a una sola
// persona: si esa no esta disponible, nadie entra. Se nombra igual para
// que quede claro de quien es la cuenta, pero se pide que entre cualquiera.
const quienAtiende = s.asignado_slack
  ? '<@' + s.asignado_slack + '>'
  : (s.asignado_a || 'nadie');

// El mensaje del cliente va citado, para que se lea de un vistazo por que
// se escalo sin tener que abrir Chatwoot.
const rawInput = s.bloqueado === 'sin_texto' ? ':studio_microphone: [Audio o archivo de voz recibido por WhatsApp]' : (s.input || '(sin texto)');
const cita = String(rawInput).split('\n').map((l) => '> ' + l).join('\n');

const linkCw = cfg.CHATWOOT_URL + '/app/accounts/' + cfg.CHATWOOT_ACCOUNT_ID +
  '/conversations/' + s.conversation_id;

const quien = s.empresa ? s.nombre + ' - ' + s.empresa : s.nombre;

// =====================================================================
// AGENDAMIENTO FUERA DE LA DISPONIBILIDAD OFRECIDA.
// El humano tiene que poder resolverlo sin abrir la ejecucion: se le dan
// las dos fechas y el horario correcto ya calculado.
// =====================================================================
const aART = (iso) => {
  if (!iso) return '(sin dato)';
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  return d.toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', weekday: 'long', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
};
let bloqueAgenda = '';
if (s.verificacion_agenda === 'fuera_de_disponibilidad') {
  bloqueAgenda = [
    '',
    ':calendar: *REVISAR EL AGENDAMIENTO* — el bot agendo un horario que Calendly no habia ofrecido.',
    '   • quedo agendado : ' + aART(s.agendado_iso),
    '   • deberia ser    : ' + (s.sugerido_iso ? aART(s.sugerido_iso) : '(ningun slot ofrecido con esa hora)'),
    '   No se le confirmo nada al cliente.'
  ].join('\n');
}

const texto = [
  s.esperando_en_reunion
    ? '<!here> :rotating_light: *ESTA ESPERANDO EN LA VIDEOLLAMADA AHORA*'
    : '<!here> :raising_hand: Un cliente pide hablar con una persona',
  '*' + quien + '*  +' + soloDigitos(s.telefono),
  s.esperando_en_reunion
    ? ':bust_in_silhouette: Es de ' + quienAtiende + ' — *si no puede, que entre cualquiera*'
    : ':bust_in_silhouette: Le toca a ' + quienAtiende,
  '',
  cita,
  '',
  bloqueAgenda,
  bloqueCard,
  ':speech_balloon: <' + linkCw + '|Responder en Chatwoot>'
].join('\n');

return [{ json: { texto_slack: texto, cards_encontradas: pages.length } }];

const item = $input.first().json || {};
let msgs = [];
if (Array.isArray(item.payload)) msgs = item.payload;
else if (Array.isArray(item)) msgs = item;
else if (item.payload && Array.isArray(item.payload.payload)) msgs = item.payload.payload;

const incoming = msgs.filter(m => m.private !== true && (m.message_type === 0 || m.message_type === "incoming"));
const latest = incoming.length ? incoming[incoming.length - 1] : null;

const attachments = (latest && Array.isArray(latest.attachments)) ? latest.attachments : [];
const audioAtt = attachments.find(a => 
  a.file_type === "audio" || 
  (a.content_type && a.content_type.startsWith("audio/")) ||
  (a.data_url && /\.(ogg|oga|mp3|wav|m4a|aac|opus)/i.test(a.data_url))
);

if (audioAtt && (audioAtt.data_url || audioAtt.url)) {
  return [{
    json: {
      tiene_audio: true,
      audio_url: audioAtt.data_url || audioAtt.url,
      audio_filename: audioAtt.file_name || "voice_note.ogg",
      message_id: latest.id,
      chatwoot_raw: item
    }
  }];
}

return [{
  json: {
    tiene_audio: false,
    audio_url: "",
    audio_filename: "",
    message_id: latest ? latest.id : null,
    chatwoot_raw: item
  }
}];

const metaAudio = $('Detectar Audio en Historial').first().json || {};
const rawPayload = metaAudio.chatwoot_raw || {};
const r = $input.first().json || {};

let text = "";
if (r.text) {
  text = r.text.trim();
} else if (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) {
  text = r.choices[0].message.content.trim();
}

const textoFinal = text ? ("[Audio]: " + text) : "[Audio inaudible o sin voz detectada]";

let msgs = [];
if (Array.isArray(rawPayload.payload)) msgs = rawPayload.payload;
else if (Array.isArray(rawPayload)) msgs = rawPayload;
else if (rawPayload.payload && Array.isArray(rawPayload.payload.payload)) msgs = rawPayload.payload.payload;

for (let i = msgs.length - 1; i >= 0; i--) {
  if (msgs[i].id === metaAudio.message_id || (!msgs[i].content && (msgs[i].message_type === 0 || msgs[i].message_type === "incoming"))) {
    msgs[i].content = textoFinal;
    break;
  }
}

return [{ json: rawPayload }];
